  1	package br.com.marealto;
  2	
  3	import br.com.marealto.handler.ApiHandler;
  4	import br.com.marealto.repository.Database;
  5	import br.com.marealto.repository.MessageRepository;
  6	import br.com.marealto.repository.ReservationRepository;
  7	import br.com.marealto.repository.RoomRepository;
  8	import br.com.marealto.service.DocumentService;
  9	import br.com.marealto.service.PricingService;
 10	import br.com.marealto.service.ReportService;
 11	import br.com.marealto.service.ReservationService;
 12	import com.fasterxml.jackson.databind.ObjectMapper;
 13	import com.fasterxml.jackson.databind.SerializationFeature;
 14	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 15	import io.javalin.Javalin;
 16	import io.javalin.json.JavalinJackson;
 17	
 18	public class App {
 19	    public static void main(String[] args) {
 20	        String dbUrl = System.getenv("DB_URL");
 21	        String dbUser = System.getenv("DB_USER");
 22	        String dbPassword = System.getenv("DB_PASSWORD");
 23	        String portStr = System.getenv("PORT");
 24	
 25	        if (dbUrl == null) {
 26	            dbUrl = "jdbc:postgresql://localhost:5432/pousada";
 27	        }
 28	        if (dbUser == null) {
 29	            dbUser = "postgres";
 30	        }
 31	        if (dbPassword == null) {
 32	            dbPassword = "postgres";
 33	        }
 34	
 35	        int port = 7070;
 36	        if (portStr != null) {
 37	            port = Integer.parseInt(portStr);
 38	        }
 39	
 40	        Database.initialize(dbUrl, dbUser, dbPassword);
 41	
 42	        RoomRepository roomRepository = new RoomRepository();
 43	        roomRepository.initializeRooms();
 44	
 45	        ReservationRepository reservationRepository = new ReservationRepository();
 46	        MessageRepository messageRepository = new MessageRepository();
 47	        PricingService pricingService = new PricingService();
 48	        DocumentService documentService = new DocumentService(pricingService);
 49	        ReservationService reservationService = new ReservationService(
 50	                roomRepository,
 51	                reservationRepository,
 52	                messageRepository,
 53	                pricingService,
 54	                documentService
 55	        );
 56	        ReportService reportService = new ReportService(roomRepository, reservationRepository);
 57	
 58	        ApiHandler apiHandler = new ApiHandler(
 59	                roomRepository,
 60	                messageRepository,
 61	                reservationService,
 62	                documentService,
 63	                reportService
 64	        );
 65	
 66	        ObjectMapper objectMapper = new ObjectMapper();
 67	        objectMapper.registerModule(new JavaTimeModule());
 68	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 69	
 70	        Javalin app = Javalin.create(config -> {
 71	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 72	        });
 73	
 74	        app.get("/rooms", apiHandler::getRooms);
 75	        app.post("/reservations", apiHandler::createReservation);
 76	        app.get("/reservations/{id}", apiHandler::getReservation);
 77	        app.post("/reservations/{id}/confirmation", apiHandler::confirmReservation);
 78	        app.post("/reservations/{id}/cancellation", apiHandler::cancelReservation);
 79	        app.post("/reservations/{id}/check-in", apiHandler::checkIn);
 80	        app.post("/reservations/{id}/check-out", apiHandler::checkOut);
 81	        app.get("/reservations/{id}/document", apiHandler::getDocument);
 82	        app.get("/messages", apiHandler::getMessages);
 83	        app.get("/reports/occupancy", apiHandler::getOccupancyReport);
 84	        app.get("/reports/revenue", apiHandler::getRevenueReport);
 85	
 86	        app.start(port);
 87	
 88	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 89	            app.stop();
 90	            Database.shutdown();
 91	        }));
 92	
 93	        System.out.println("Pousada Maré Alta sistema iniciado na porta " + port);
 94	    }
 95	}
 96	package br.com.marealto.handler;
 97	
 98	import br.com.marealto.dto.*;
