118	    private final MessageRepository messageRepository;
119	    private final ReservationService reservationService;
120	    private final DocumentService documentService;
121	    private final ReportService reportService;
122	
123	    public ApiHandler(
124	            RoomRepository roomRepository,
125	            MessageRepository messageRepository,
126	            ReservationService reservationService,
127	            DocumentService documentService,
128	            ReportService reportService) {
129	        this.roomRepository = roomRepository;
130	        this.messageRepository = messageRepository;
131	        this.reservationService = reservationService;
132	        this.documentService = documentService;
133	        this.reportService = reportService;
134	    }
135	
136	    public void getRooms(Context ctx) {
137	        List<Room> rooms = roomRepository.findAll();
138	        List<RoomResponse> response = rooms.stream()
139	                .map(RoomResponse::from)
140	                .collect(Collectors.toList());
141	        ctx.json(response);
142	    }
143	
144	    public void createReservation(Context ctx) {
145	        try {
146	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
147	            request.validate();
148	
149	            Reservation reservation = reservationService.createReservation(request.toReservation());
150	            ReservationResponse response = ReservationResponse.from(reservation);
151	
152	            ctx.status(201).json(response);
153	        } catch (ReservationService.InvalidRequestException e) {
154	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
155	        } catch (ReservationService.RoomNotFoundException e) {
156	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
157	        } catch (ReservationService.RoomUnavailableException e) {
158	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
159	        } catch (ReservationService.CapacityExceededException e) {
160	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
161	        } catch (DateTimeParseException e) {
162	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
163	        } catch (Exception e) {
164	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
165	        }
166	    }
