245	    public void getDocument(Context ctx) {
246	        try {
247	            Long id = Long.parseLong(ctx.pathParam("id"));
248	            Reservation reservation = reservationService.getReservation(id);
249	
250	            if (reservation.getStatus() == ReservationStatus.PENDING) {
251	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED",
252	                    "Document is only available for paid reservations"));
253	                return;
254	            }
255	
256	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
257	            String documentText = documentService.generateDocument(reservation, room.getType());
258	            DocumentResponse response = DocumentResponse.from(reservation, room.getType(), documentText);
259	
260	            ctx.json(response);
261	        } catch (NumberFormatException e) {
262	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
263	        } catch (ReservationService.ReservationNotFoundException e) {
264	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
265	        }
266	    }
267	
268	    public void getMessages(Context ctx) {
269	        List<Message> messages = messageRepository.findAll();
270	        List<MessageResponse> response = messages.stream()
271	                .map(MessageResponse::from)
272	                .collect(Collectors.toList());
273	        ctx.json(response);
274	    }
275	
276	    public void getOccupancyReport(Context ctx) {
277	        try {
278	            String dateStr = ctx.queryParam("date");
279	            if (dateStr == null) {
280	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
281	                return;
282	            }
283	
284	            LocalDate date = LocalDate.parse(dateStr);
285	            String csv = reportService.generateOccupancyReport(date);
286	
287	            ctx.contentType("text/csv; charset=utf-8");
288	            ctx.result(csv);
289	        } catch (DateTimeParseException e) {
290	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
291	        }
292	    }
293	
294	    public void getRevenueReport(Context ctx) {
295	        try {
296	            String monthStr = ctx.queryParam("month");
297	            if (monthStr == null) {
298	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
299	                return;
300	            }
301	
302	            YearMonth month = YearMonth.parse(monthStr);
303	            String csv = reportService.generateRevenueReport(month);
304	
305	            ctx.contentType("text/csv; charset=utf-8");
306	            ctx.result(csv);
307	        } catch (DateTimeParseException e) {
308	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
309	        }
310	    }
311	}

