 29	    public String generateDocument(Reservation reservation, RoomType roomType) {
 30	        GuestIdentification id = reservation.getGuestIdentification();
 31	
 32	        if (id instanceof GuestIdentification.Individual) {
 33	            return generateReceipt(reservation, roomType);
 34	        } else if (id instanceof GuestIdentification.Company) {
 35	            return generateInvoice(reservation, roomType);
 36	        } else if (id instanceof GuestIdentification.Foreign) {
 37	            return generateBookingReceipt(reservation, roomType);
 38	        }
 39	
 40	        throw new IllegalStateException("Unknown identification type");
 41	    }
