 43	    private String generateReceipt(Reservation reservation, RoomType roomType) {
 44	        StringBuilder sb = new StringBuilder();
 45	        GuestIdentification.Individual individual = (GuestIdentification.Individual) reservation.getGuestIdentification();
 46	
 47	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 48	        sb.append("Hóspede: ").append(reservation.getGuestName())
