 56	
 57	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 58	            sb.append("Desconto: ").append(brFormat.format(reservation.getDiscount())).append("\n");
 59	        }
 60	
 61	        sb.append("Total: ").append(brFormat.format(reservation.getTotal()));
