105	          .append(" | ").append(formatNightsEn(reservation.getNights())).append("\n");
106	        sb.append("Nights: BRL ").append(enFormat.format(reservation.getSubtotal())).append("\n");
107	
108	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
