138	    private String formatCpf(String cpf) {
139	        if (cpf.length() == 11) {
140	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
141	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
142	        }
143	        return cpf;
144	    }
