146	    private String formatCnpj(String cnpj) {
147	        if (cnpj.length() == 14) {
148	            return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
149	                   cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
150	        }
151	        return cnpj;
