156	import br.com.marealto.model.RatePlan;
157	import br.com.marealto.model.Room;
158	
159	import java.math.BigDecimal;
160	import java.math.RoundingMode;
161	import java.time.LocalDate;
162	
163	public class PricingService {
164	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
165	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
166	
167	    public boolean isHighSeason(LocalDate date) {
168	        int month = date.getMonthValue();
169	        int day = date.getDayOfMonth();
170	
171	        if (month == 12 && day >= 15) {
172	            return true;
173	        }
174	
175	        if (month == 1 || month == 2) {
176	            return true;
177	        }
178	
179	        if (month == 7) {
180	            return true;
181	        }
182	
183	        return false;
184	    }
185	
186	    public BigDecimal calculateNightPrice(Room room, LocalDate date) {
187	        BigDecimal basePrice = room.getNightlyRate();
188	
189	        if (isHighSeason(date)) {
190	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
191	        }
192	
193	        return basePrice.setScale(2, RoundingMode.HALF_EVEN);
194	    }
195	
196	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
197	        BigDecimal subtotal = BigDecimal.ZERO;
198	        LocalDate currentDate = checkIn;
199	
200	        while (currentDate.isBefore(checkOut)) {
201	            BigDecimal nightPrice = calculateNightPrice(room, currentDate);
202	            subtotal = subtotal.add(nightPrice);
203	            currentDate = currentDate.plusDays(1);
204	        }
205	
206	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
207	    }
208	
209	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
210	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
211	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
212	        }
213	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
214	    }
215	
216	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
217	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
218	    }
219	
220	    public BigDecimal calculateIss(BigDecimal total) {
221	        return total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_EVEN);
222	    }
223	}
