312	
313	public class ReservationService {
314	    private final RoomRepository roomRepository;
315	    private final ReservationRepository reservationRepository;
316	    private final MessageRepository messageRepository;
317	    private final PricingService pricingService;
318	    private final DocumentService documentService;
319	
320	    public ReservationService(
321	            RoomRepository roomRepository,
322	            ReservationRepository reservationRepository,
323	            MessageRepository messageRepository,
324	            PricingService pricingService,
325	            DocumentService documentService) {
326	        this.roomRepository = roomRepository;
327	        this.reservationRepository = reservationRepository;
328	        this.messageRepository = messageRepository;
329	        this.pricingService = pricingService;
330	        this.documentService = documentService;
331	    }
332	
333	    public Reservation createReservation(Reservation reservation) {
334	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
335	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
336	
337	        if (reservation.getGuests() > room.getCapacity()) {
338	            throw new CapacityExceededException("Number of guests exceeds room capacity");
339	        }
340	
341	        if (reservation.getGuests() < 1) {
342	            throw new InvalidRequestException("At least one guest is required");
343	        }
344	
345	        if (!reservation.getCheckOut().isAfter(reservation.getCheckIn())) {
346	            throw new InvalidRequestException("Check-out must be after check-in");
347	        }
348	
349	        List<Reservation> conflicts = reservationRepository.findConflicting(
350	                reservation.getRoomNumber(),
351	                reservation.getCheckIn(),
352	                reservation.getCheckOut()
353	        );
354	
355	        if (!conflicts.isEmpty()) {
356	            throw new RoomUnavailableException("Room is not available for the selected dates");
357	        }
358	
359	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
360	        BigDecimal subtotal = pricingService.calculateSubtotal(room, reservation.getCheckIn(), reservation.getCheckOut());
361	        BigDecimal discount = pricingService.calculateDiscount(subtotal, reservation.getRatePlan());
362	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
363	
364	        reservation.setNights(nights);
365	        reservation.setSubtotal(subtotal);
366	        reservation.setDiscount(discount);
367	        reservation.setTotal(total);
368	        reservation.setStatus(ReservationStatus.PENDING);
369	        reservation.setAmountPaid(BigDecimal.ZERO);
370	
371	        return reservationRepository.save(reservation);
372	    }
373	
374	    public Reservation confirmReservation(Long id) {
375	        Reservation reservation = reservationRepository.findById(id)
376	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
377	
378	        if (reservation.getStatus() != ReservationStatus.PENDING) {
379	            throw new OperationNotAllowedException("Can only confirm pending reservations");
380	        }
381	
382	        reservation.setStatus(ReservationStatus.CONFIRMED);
383	        reservation.setAmountPaid(reservation.getTotal());
384	        reservationRepository.update(reservation);
385	
386	        sendConfirmationEmail(reservation);
387	
388	        return reservation;
389	    }
390	
391	    public Reservation cancelReservation(Long id) {
392	        Reservation reservation = reservationRepository.findById(id)
393	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
394	
395	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
396	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
397	            reservation.getStatus() == ReservationStatus.CANCELLED) {
398	            throw new OperationNotAllowedException("Cannot cancel reservation in current status");
399	        }
400	
401	        reservation.setStatus(ReservationStatus.CANCELLED);
402	
403	        if (reservation.getRatePlan() == RatePlan.STANDARD &&
404	            reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
405	            reservation.setRefund(reservation.getAmountPaid());
406	        } else {
407	            reservation.setRefund(BigDecimal.ZERO);
408	        }
409	
410	        reservationRepository.update(reservation);
411	
412	        return reservation;
413	    }
414	
415	    public Reservation checkIn(Long id) {
416	        Reservation reservation = reservationRepository.findById(id)
417	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
418	
419	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
420	            throw new OperationNotAllowedException("Can only check in confirmed reservations");
421	        }
422	
423	        reservation.setStatus(ReservationStatus.CHECKED_IN);
424	        reservationRepository.update(reservation);
425	
426	        return reservation;
427	    }
428	
429	    public Reservation checkOut(Long id) {
430	        Reservation reservation = reservationRepository.findById(id)
431	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
432	
433	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
434	            throw new OperationNotAllowedException("Can only check out guests who checked in");
435	        }
436	
437	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
438	        reservationRepository.update(reservation);
439	
440	        return reservation;
441	    }
442	
443	    public Reservation getReservation(Long id) {
444	        return reservationRepository.findById(id)
445	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
446	    }
447	
448	    private void sendConfirmationEmail(Reservation reservation) {
449	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
450	        String emailBody = documentService.generateConfirmationEmail(reservation, room.getType());
451	
452	        Message message = new Message(
453	                "EMAIL",
454	                reservation.getGuestEmail(),
455	                "Reserva confirmada - Pousada Maré Alta",
456	                emailBody
457	        );
458	
459	        messageRepository.save(message);
460	    }
