241	    public ReportService(RoomRepository roomRepository, ReservationRepository reservationRepository) {
242	        this.roomRepository = roomRepository;
243	        this.reservationRepository = reservationRepository;
244	    }
245	
246	    public String generateOccupancyReport(LocalDate date) {
247	        List<Reservation> reservations = reservationRepository.findByNight(date);
248	        List<Room> allRooms = roomRepository.findAll();
249	
250	        StringBuilder csv = new StringBuilder();
251	        csv.append("room,type,reservation,check_in,check_out\n");
252	
253	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
254	
255	        for (Reservation reservation : reservations) {
256	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
257	            csv.append(reservation.getRoomNumber()).append(",");
258	            csv.append(room.getType().name()).append(",");
259	            csv.append(reservation.getId()).append(",");
260	            csv.append(reservation.getCheckIn().format(formatter)).append(",");
261	            csv.append(reservation.getCheckOut().format(formatter)).append("\n");
262	        }
263	
264	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
265	
266	        return csv.toString();
267	    }
268	
269	    public String generateRevenueReport(YearMonth month) {
270	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
271	
272	        StringBuilder csv = new StringBuilder();
273	        csv.append("reservation,room,check_in,check_out,status,amount\n");
274	
275	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
276	        BigDecimal total = BigDecimal.ZERO;
277	
278	        for (Reservation reservation : reservations) {
279	            BigDecimal revenue = reservation.getAmountPaid();
280	            if (reservation.getRefund() != null) {
281	                revenue = revenue.subtract(reservation.getRefund());
282	            }
283	
284	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
285	                csv.append(reservation.getId()).append(",");
286	                csv.append(reservation.getRoomNumber()).append(",");
287	                csv.append(reservation.getCheckIn().format(formatter)).append(",");
288	                csv.append(reservation.getCheckOut().format(formatter)).append(",");
289	                csv.append(reservation.getStatus().name()).append(",");
290	                csv.append(revenue.setScale(2).toPlainString()).append("\n");
291	
292	                total = total.add(revenue);
293	            }
294	        }
295	
296	        csv.append("total,").append(total.setScale(2).toPlainString());
297	
298	        return csv.toString();
299	    }
