  1	package br.com.marealto.repository;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	
  6	import javax.sql.DataSource;
  7	import java.sql.Connection;
  8	import java.sql.SQLException;
  9	import java.sql.Statement;
 10	
 11	public class Database {
 12	    private static HikariDataSource dataSource;
 13	
 14	    public static void initialize(String url, String user, String password) {
 15	        HikariConfig config = new HikariConfig();
 16	        config.setJdbcUrl(url);
 17	        config.setUsername(user);
 18	        config.setPassword(password);
 19	        config.setMaximumPoolSize(10);
 20	
 21	        dataSource = new HikariDataSource(config);
 22	
 23	        createTables();
 24	    }
 25	
 26	    public static DataSource getDataSource() {
 27	        return dataSource;
 28	    }
 29	
 30	    public static Connection getConnection() throws SQLException {
 31	        return dataSource.getConnection();
 32	    }
 33	
 34	    private static void createTables() {
 35	        try (Connection conn = getConnection();
 36	             Statement stmt = conn.createStatement()) {
 37	
 38	            stmt.execute("""
 39	                CREATE TABLE IF NOT EXISTS rooms (
 40	                    number VARCHAR(10) PRIMARY KEY,
 41	                    type VARCHAR(20) NOT NULL,
 42	                    capacity INTEGER NOT NULL,
 43	                    nightly_rate DECIMAL(10, 2) NOT NULL
 44	                )
 45	            """);
 46	
 47	            stmt.execute("""
 48	                CREATE TABLE IF NOT EXISTS reservations (
 49	                    id SERIAL PRIMARY KEY,
 50	                    room_number VARCHAR(10) NOT NULL,
 51	                    guest_name VARCHAR(255) NOT NULL,
 52	                    guest_email VARCHAR(255) NOT NULL,
 53	                    guest_cpf VARCHAR(14),
 54	                    company_cnpj VARCHAR(18),
 55	                    company_name VARCHAR(255),
 56	                    guest_passport VARCHAR(50),
 57	                    guest_country VARCHAR(100),
 58	                    check_in DATE NOT NULL,
 59	                    check_out DATE NOT NULL,
 60	                    guests INTEGER NOT NULL,
 61	                    rate_plan VARCHAR(20) NOT NULL,
 62	                    nights INTEGER NOT NULL,
 63	                    subtotal DECIMAL(10, 2) NOT NULL,
 64	                    discount DECIMAL(10, 2) NOT NULL,
 65	                    total DECIMAL(10, 2) NOT NULL,
 66	                    status VARCHAR(20) NOT NULL,
 67	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 68	                    refund DECIMAL(10, 2),
 69	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
 70	                )
 71	            """);
 72	
 73	            stmt.execute("""
 74	                CREATE TABLE IF NOT EXISTS messages (
 75	                    id SERIAL PRIMARY KEY,
 76	                    channel VARCHAR(20) NOT NULL,
 77	                    recipient VARCHAR(255) NOT NULL,
 78	                    subject VARCHAR(500) NOT NULL,
 79	                    body TEXT NOT NULL
 80	                )
 81	            """);
 82	
 83	        } catch (SQLException e) {
 84	            throw new RuntimeException("Failed to create tables", e);
 85	        }
 86	    }
 87	
 88	    public static void shutdown() {
 89	        if (dataSource != null) {
 90	            dataSource.close();
 91	        }
 92	    }
 93	}
