102	public class MessageRepository {
103	
104	    public Message save(Message message) {
105	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
106	
107	        try (Connection conn = Database.getConnection();
108	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
109	
110	            stmt.setString(1, message.getChannel());
111	            stmt.setString(2, message.getTo());
112	            stmt.setString(3, message.getSubject());
113	            stmt.setString(4, message.getBody());
114	
115	            stmt.executeUpdate();
116	
117	            try (ResultSet rs = stmt.getGeneratedKeys()) {
118	                if (rs.next()) {
119	                    message.setId(rs.getLong(1));
120	                }
121	            }
122	
123	            return message;
124	        } catch (SQLException e) {
125	            throw new RuntimeException("Failed to save message", e);
126	        }
127	    }
