129	    public List<Message> findAll() {
130	        List<Message> messages = new ArrayList<>();
131	        String sql = "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id";
132	
133	        try (Connection conn = Database.getConnection();
134	             PreparedStatement stmt = conn.prepareStatement(sql);
135	             ResultSet rs = stmt.executeQuery()) {
136	
137	            while (rs.next()) {
138	                Message message = new Message();
139	                message.setId(rs.getLong("id"));
140	                message.setChannel(rs.getString("channel"));
141	                message.setTo(rs.getString("recipient"));
142	                message.setSubject(rs.getString("subject"));
143	                message.setBody(rs.getString("body"));
144	                messages.add(message);
145	            }
146	        } catch (SQLException e) {
147	            throw new RuntimeException("Failed to fetch messages", e);
148	        }
149	
150	        return messages;
151	    }
