164	
165	public class ReservationRepository {
166	
167	    public Reservation save(Reservation reservation) {
168	        String sql = """
169	            INSERT INTO reservations (
170	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
171	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
172	                nights, subtotal, discount, total, status, amount_paid, refund
173	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
174	        """;
175	
176	        try (Connection conn = Database.getConnection();
177	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
178	
179	            setReservationParameters(stmt, reservation);
180	
181	            stmt.executeUpdate();
182	
183	            try (ResultSet rs = stmt.getGeneratedKeys()) {
184	                if (rs.next()) {
185	                    reservation.setId(rs.getLong(1));
186	                }
187	            }
188	
189	            return reservation;
190	        } catch (SQLException e) {
191	            throw new RuntimeException("Failed to save reservation", e);
192	        }
193	    }
194	
195	    public void update(Reservation reservation) {
196	        String sql = """
197	            UPDATE reservations SET
198	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?, company_cnpj = ?,
199	                company_name = ?, guest_passport = ?, guest_country = ?, check_in = ?, check_out = ?,
200	                guests = ?, rate_plan = ?, nights = ?, subtotal = ?, discount = ?, total = ?,
201	                status = ?, amount_paid = ?, refund = ?
202	            WHERE id = ?
203	        """;
204	
205	        try (Connection conn = Database.getConnection();
206	             PreparedStatement stmt = conn.prepareStatement(sql)) {
207	
208	            setReservationParameters(stmt, reservation);
209	            stmt.setLong(20, reservation.getId());
210	
211	            stmt.executeUpdate();
212	        } catch (SQLException e) {
213	            throw new RuntimeException("Failed to update reservation", e);
214	        }
215	    }
216	
217	    private void setReservationParameters(PreparedStatement stmt, Reservation r) throws SQLException {
218	        stmt.setString(1, r.getRoomNumber());
219	        stmt.setString(2, r.getGuestName());
220	        stmt.setString(3, r.getGuestEmail());
221	
222	        GuestIdentification id = r.getGuestIdentification();
223	        if (id instanceof GuestIdentification.Individual individual) {
224	            stmt.setString(4, individual.cpf());
225	            stmt.setNull(5, Types.VARCHAR);
226	            stmt.setNull(6, Types.VARCHAR);
227	            stmt.setNull(7, Types.VARCHAR);
228	            stmt.setNull(8, Types.VARCHAR);
229	        } else if (id instanceof GuestIdentification.Company company) {
230	            stmt.setNull(4, Types.VARCHAR);
231	            stmt.setString(5, company.cnpj());
232	            stmt.setString(6, company.companyName());
233	            stmt.setNull(7, Types.VARCHAR);
234	            stmt.setNull(8, Types.VARCHAR);
235	        } else if (id instanceof GuestIdentification.Foreign foreign) {
236	            stmt.setNull(4, Types.VARCHAR);
237	            stmt.setNull(5, Types.VARCHAR);
238	            stmt.setNull(6, Types.VARCHAR);
239	            stmt.setString(7, foreign.passport());
240	            stmt.setString(8, foreign.country());
241	        }
242	
243	        stmt.setDate(9, Date.valueOf(r.getCheckIn()));
244	        stmt.setDate(10, Date.valueOf(r.getCheckOut()));
245	        stmt.setInt(11, r.getGuests());
246	        stmt.setString(12, r.getRatePlan().name());
247	        stmt.setInt(13, r.getNights());
248	        stmt.setBigDecimal(14, r.getSubtotal());
249	        stmt.setBigDecimal(15, r.getDiscount());
250	        stmt.setBigDecimal(16, r.getTotal());
251	        stmt.setString(17, r.getStatus().name());
252	        stmt.setBigDecimal(18, r.getAmountPaid());
253	
254	        if (r.getRefund() != null) {
255	            stmt.setBigDecimal(19, r.getRefund());
256	        } else {
257	            stmt.setNull(19, Types.DECIMAL);
258	        }
259	    }
260	
261	    public Optional<Reservation> findById(Long id) {
262	        String sql = "SELECT * FROM reservations WHERE id = ?";
263	
264	        try (Connection conn = Database.getConnection();
265	             PreparedStatement stmt = conn.prepareStatement(sql)) {
266	
267	            stmt.setLong(1, id);
268	
269	            try (ResultSet rs = stmt.executeQuery()) {
270	                if (rs.next()) {
271	                    return Optional.of(mapReservation(rs));
272	                }
273	            }
274	        } catch (SQLException e) {
275	            throw new RuntimeException("Failed to fetch reservation", e);
276	        }
277	
278	        return Optional.empty();
279	    }
280	
281	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
282	        String sql = """
283	            SELECT * FROM reservations
284	            WHERE room_number = ?
285	            AND status NOT IN ('CANCELLED')
286	            AND check_in < ?
287	            AND check_out > ?
288	        """;
289	
290	        List<Reservation> reservations = new ArrayList<>();
291	
292	        try (Connection conn = Database.getConnection();
293	             PreparedStatement stmt = conn.prepareStatement(sql)) {
294	
295	            stmt.setString(1, roomNumber);
296	            stmt.setDate(2, Date.valueOf(checkOut));
297	            stmt.setDate(3, Date.valueOf(checkIn));
298	
299	            try (ResultSet rs = stmt.executeQuery()) {
300	                while (rs.next()) {
301	                    reservations.add(mapReservation(rs));
302	                }
303	            }
304	        } catch (SQLException e) {
305	            throw new RuntimeException("Failed to check conflicts", e);
306	        }
307	
308	        return reservations;
309	    }
310	
311	    public List<Reservation> findByCheckInMonth(YearMonth month) {
312	        String sql = """
313	            SELECT * FROM reservations
314	            WHERE EXTRACT(YEAR FROM check_in) = ?
315	            AND EXTRACT(MONTH FROM check_in) = ?
316	            AND status != 'PENDING'
317	            ORDER BY check_in, id
318	        """;
319	
320	        List<Reservation> reservations = new ArrayList<>();
321	
322	        try (Connection conn = Database.getConnection();
323	             PreparedStatement stmt = conn.prepareStatement(sql)) {
324	
325	            stmt.setInt(1, month.getYear());
326	            stmt.setInt(2, month.getMonthValue());
327	
328	            try (ResultSet rs = stmt.executeQuery()) {
329	                while (rs.next()) {
330	                    reservations.add(mapReservation(rs));
331	                }
332	            }
333	        } catch (SQLException e) {
334	            throw new RuntimeException("Failed to fetch reservations by month", e);
335	        }
336	
337	        return reservations;
338	    }
339	
340	    public List<Reservation> findByNight(LocalDate night) {
341	        String sql = """
342	            SELECT * FROM reservations
343	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
344	            AND check_in <= ?
345	            AND check_out > ?
346	            ORDER BY room_number
347	        """;
348	
349	        List<Reservation> reservations = new ArrayList<>();
350	
351	        try (Connection conn = Database.getConnection();
352	             PreparedStatement stmt = conn.prepareStatement(sql)) {
353	
354	            stmt.setDate(1, Date.valueOf(night));
355	            stmt.setDate(2, Date.valueOf(night));
356	
357	            try (ResultSet rs = stmt.executeQuery()) {
358	                while (rs.next()) {
359	                    reservations.add(mapReservation(rs));
360	                }
361	            }
362	        } catch (SQLException e) {
363	            throw new RuntimeException("Failed to fetch reservations by night", e);
364	        }
365	
366	        return reservations;
367	    }
368	
369	    private Reservation mapReservation(ResultSet rs) throws SQLException {
370	        Reservation r = new Reservation();
371	        r.setId(rs.getLong("id"));
372	        r.setRoomNumber(rs.getString("room_number"));
373	        r.setGuestName(rs.getString("guest_name"));
374	        r.setGuestEmail(rs.getString("guest_email"));
375	
376	        String cpf = rs.getString("guest_cpf");
377	        String cnpj = rs.getString("company_cnpj");
378	        String passport = rs.getString("guest_passport");
379	
380	        if (cpf != null) {
381	            r.setGuestIdentification(new GuestIdentification.Individual(cpf));
382	        } else if (cnpj != null) {
383	            r.setGuestIdentification(new GuestIdentification.Company(cnpj, rs.getString("company_name")));
384	        } else if (passport != null) {
385	            r.setGuestIdentification(new GuestIdentification.Foreign(passport, rs.getString("guest_country")));
386	        }
387	
388	        r.setCheckIn(rs.getDate("check_in").toLocalDate());
389	        r.setCheckOut(rs.getDate("check_out").toLocalDate());
390	        r.setGuests(rs.getInt("guests"));
391	        r.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
392	        r.setNights(rs.getInt("nights"));
393	        r.setSubtotal(rs.getBigDecimal("subtotal"));
394	        r.setDiscount(rs.getBigDecimal("discount"));
395	        r.setTotal(rs.getBigDecimal("total"));
396	        r.setStatus(ReservationStatus.valueOf(rs.getString("status")));
397	        r.setAmountPaid(rs.getBigDecimal("amount_paid"));
398	
399	        BigDecimal refund = rs.getBigDecimal("refund");
400	        if (!rs.wasNull()) {
401	            r.setRefund(refund);
402	        }
403	
404	        return r;
405	    }
406	}
