  2	
  3	import br.com.marealto.model.GuestIdentification;
  4	import br.com.marealto.model.RatePlan;
  5	import br.com.marealto.model.Reservation;
  6	import br.com.marealto.service.ReservationService;
  7	import com.fasterxml.jackson.annotation.JsonProperty;
  8	
  9	import java.time.LocalDate;
 10	
 11	public record CreateReservationRequest(
 12	        @JsonProperty("roomNumber") String roomNumber,
 13	        @JsonProperty("guestName") String guestName,
 14	        @JsonProperty("guestEmail") String guestEmail,
 15	        @JsonProperty("guestCpf") String guestCpf,
 16	        @JsonProperty("companyCnpj") String companyCnpj,
 17	        @JsonProperty("companyName") String companyName,
 18	        @JsonProperty("guestPassport") String guestPassport,
 19	        @JsonProperty("guestCountry") String guestCountry,
 20	        @JsonProperty("checkIn") LocalDate checkIn,
 21	        @JsonProperty("checkOut") LocalDate checkOut,
 22	        int guests,
 23	        @JsonProperty("ratePlan") RatePlan ratePlan
 24	) {
 25	    public Reservation toReservation() {
 26	        GuestIdentification identification = parseIdentification();
 27	
 28	        Reservation reservation = new Reservation();
 29	        reservation.setRoomNumber(roomNumber);
 30	        reservation.setGuestName(guestName);
 31	        reservation.setGuestEmail(guestEmail);
 32	        reservation.setGuestIdentification(identification);
 33	        reservation.setCheckIn(checkIn);
 34	        reservation.setCheckOut(checkOut);
 35	        reservation.setGuests(guests);
 36	        reservation.setRatePlan(ratePlan);
 37	
 38	        return reservation;
 39	    }
 40	
 41	    private GuestIdentification parseIdentification() {
 42	        int count = 0;
 43	        GuestIdentification result = null;
 44	
 45	        if (guestCpf != null) {
 46	            count++;
 47	            result = new GuestIdentification.Individual(guestCpf);
 48	        }
 49	
 50	        if (companyCnpj != null && companyName != null) {
 51	            count++;
 52	            result = new GuestIdentification.Company(companyCnpj, companyName);
 53	        } else if (companyCnpj != null || companyName != null) {
 54	            throw new ReservationService.InvalidRequestException("Both companyCnpj and companyName are required");
 55	        }
 56	
 57	        if (guestPassport != null && guestCountry != null) {
 58	            count++;
