 20	    }
 21	
 22	    @Test
 23	    void testGenerateReceiptForIndividual() {
 24	        Reservation reservation = new Reservation();
 25	        reservation.setId(7L);
 26	        reservation.setRoomNumber("201");
 27	        reservation.setGuestName("Carla Dias");
 28	        reservation.setGuestEmail("carla@example.com");
 29	        reservation.setGuestIdentification(new GuestIdentification.Individual("11122233344"));
 30	        reservation.setCheckIn(LocalDate.of(2027, 3, 10));
 31	        reservation.setCheckOut(LocalDate.of(2027, 3, 12));
 32	        reservation.setNights(2);
 33	        reservation.setSubtotal(new BigDecimal("779.80"));
 34	        reservation.setDiscount(new BigDecimal("0.00"));
 35	        reservation.setTotal(new BigDecimal("779.80"));
 36	
 37	        String document = documentService.generateDocument(reservation, RoomType.DELUXE);
 38	
 39	        assertTrue(document.contains("Comprovante de reserva nº 7"));
 40	        assertTrue(document.contains("Carla Dias"));
 41	        assertTrue(document.contains("111.222.333-44"));
 42	        assertTrue(document.contains("201 (DELUXE)"));
 43	        assertTrue(document.contains("10/03/2027"));
 44	        assertTrue(document.contains("12/03/2027"));
 45	        assertTrue(document.contains("2 diárias"));
 46	        assertTrue(document.contains("R$"));
 47	        assertTrue(document.contains("779,80"));
 48	    }
